INSERT INTO variant_attribute_value (id, attribute_value_id, variant_id)
SELECT
    ('aa' || substr(replace(variant.id::text, '-', ''), 3, 30))::uuid,
    CASE
        WHEN variant.product_id::text LIKE 'b110%' AND right(variant.id::text, 1) IN ('1','3','5','7','9')
            THEN 'f1100000-0000-0000-0000-000000000001'::uuid
        WHEN variant.product_id::text LIKE 'b110%'
            THEN 'f1100000-0000-0000-0000-000000000002'::uuid
        WHEN right(variant.id::text, 1) IN ('1','3','5','7','9')
            THEN 'f1200000-0000-0000-0000-000000000001'::uuid
        ELSE 'f1200000-0000-0000-0000-000000000002'::uuid
    END,
    variant.id
FROM product_variants variant
WHERE variant.product_id IN (
    'b1100000-0000-0000-0000-000000000001', 'b1100000-0000-0000-0000-000000000002',
    'b1100000-0000-0000-0000-000000000003', 'b1100000-0000-0000-0000-000000000004',
    'b1100000-0000-0000-0000-000000000005', 'b1200000-0000-0000-0000-000000000001',
    'b1200000-0000-0000-0000-000000000002', 'b1200000-0000-0000-0000-000000000003',
    'b1200000-0000-0000-0000-000000000004', 'b1200000-0000-0000-0000-000000000005'
)
ON CONFLICT (id) DO UPDATE SET
    attribute_value_id = EXCLUDED.attribute_value_id,
    variant_id = EXCLUDED.variant_id;

INSERT INTO product_images (id, image_type, image_url, product_id, variant_id)
SELECT
    ('ab' || substr(replace(product.id::text, '-', ''), 3, 30))::uuid,
    'PRODUCT', product.thumbnail_img, product.id, NULL
FROM products product
WHERE product.shop_id IN (
    '91000000-0000-0000-0000-000000000001',
    '91000000-0000-0000-0000-000000000002'
)
ON CONFLICT (id) DO UPDATE SET
    image_type = EXCLUDED.image_type,
    image_url = EXCLUDED.image_url,
    product_id = EXCLUDED.product_id,
    variant_id = EXCLUDED.variant_id;

COMMIT;


